import {taskNotes} from './curriculum.js';
import {weeks} from './schedule.js';
import {essayMilestones} from './journey.js';
import {collectEvidence,insertPassage,projectDesk,relationDiagram,deliveryHtml,annexOptions,alertHtml} from './seminar.js';
import {glossaryLinks,conceptHtml,conceptById} from './glossary.js';
import {teachingPlan,evaluationView,activityLinks} from './teaching.js';
import {resources,resourceById,translationRows} from './corpus.js';
import {modules,moduleById,steps,history,schools,diagnostic,rubric} from './course.js';
import {STORAGE_KEY,freshState,loadState,writeNote,markReviewed,workStatus,hasWork,wordCount,exportMarkdown,validateState,fileName,moduleKeys,moduleWorkStatus,fieldNames,keyNames,routeKey,noteDestination,activityProgress,archivedKeys,fieldLabel} from './state.js';

import {createPresenter} from './presenter.js';
import {createSession} from './session.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}
const loaded=loadState(storage);let state=loaded.state,storageBlocked=!!loaded.error;
let current={page:'inicio',module:1,step:'orientar'},pendingImport=null,toastTimer;
const main=$('#main');
// In the catalogue installation the return is relative; standalone local work uses its local preview.
const catalogHref=location.pathname.includes('/recursos/literatura-comparada/')?'../../recursos.html':/^(127\.0\.0\.1|localhost)$/.test(location.hostname)?'http://127.0.0.1:4184/recursos.html':'/recursos.html';
document.querySelectorAll('[data-catalog-link]').forEach(a=>{a.href=catalogHref;if(!location.pathname.includes('/recursos/literatura-comparada/')){a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label',a.textContent+' (abre en otra pestaña)');}});
const lock=navigator.locks?fn=>navigator.locks.request('lc-cuaderno-write',fn):null;
let session=createSession({storage,lock,initialRaw:loaded.raw}),savePhase=storageBlocked?'unavailable':'saved',pendingSaves=0,saveAnnouncement,lastAnnounced='',relationEdit=-1,mutationBusy=false;
const count=(n,one,many)=>`${n} ${n===1?one:many}`;
let lastEdited='',savedTagTimer,localSave=false,announcedPhase=savePhase;
function showSavedTag(){const tag=lastEdited&&document.querySelector(`[data-saved-for="${lastEdited}"]`);lastEdited='';if(!tag)return;document.querySelectorAll('[data-saved-for]').forEach(t=>t.textContent='');tag.textContent='Guardado';clearTimeout(savedTagTimer);savedTagTimer=setTimeout(()=>tag.textContent='',2500);}
const sameDay=iso=>new Date(iso).toDateString()===new Date().toDateString();
function storedRaw(){try{return storage.getItem(STORAGE_KEY);}catch{return undefined;}}
const clock=(iso,seconds)=>new Date(iso).toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{})});
function savedLabel(seconds=true){if(locked)return 'Cuaderno oculto hasta confirmar que es tuyo';if(savePhase==='conflict')return 'No se guarda · otra pestaña cambió el cuaderno';if(savePhase==='unavailable')return 'No se guarda · descarga una copia';if(pendingSaves)return 'Guardando…';return state.updatedAt?(sameDay(state.updatedAt)?'Guardado a las '+clock(state.updatedAt,seconds):'Guardado el '+new Date(state.updatedAt).toLocaleDateString('es',{day:'numeric',month:'long'})+' a las '+clock(state.updatedAt,false)):'Se guarda sólo en este navegador al escribir';}
// Announce state changes, not every pause in typing: the spoken label has minute precision.
function updateSaveStatus(){document.body.dataset.save=savePhase;document.querySelectorAll('[data-save-status]').forEach(el=>el.textContent=savedLabel());clearTimeout(saveAnnouncement);saveAnnouncement=setTimeout(()=>{const text=savedLabel(false),phaseChanged=savePhase!==announcedPhase;announcedPhase=savePhase;if((phaseChanged||localSave)&&text!==lastAnnounced&&text!=='Guardando…'){lastAnnounced=text;$('#save-announcement').textContent=text;}localSave=false;},1000);}
// Sticky sidebar and evidence panel move down by the warning's height instead of hiding under it.
const warningSize=new ResizeObserver(()=>document.documentElement.style.setProperty('--warning-h',($('#storage-warning')?.offsetHeight||0)+'px'));
function storageNotice(reason){if(reason!=='deleted'){savePhase=reason;}let warning=$('#storage-warning');if(warning?.dataset.reason===reason){updateSaveStatus();return;}if(!warning){warning=document.createElement('section');warning.id='storage-warning';warning.className='storage-warning';warning.setAttribute('aria-label','Conservación del cuaderno');$('.topbar').after(warning);warningSize.observe(warning);}warning.dataset.reason=reason;warning.innerHTML=reason==='conflict'?`<div role="alert"><strong>Otra pestaña cambió el cuaderno. Esta pestaña dejó de guardar.</strong><p>Tus textos siguen aquí, pero no se guardan para no sobrescribir los de la otra pestaña. Elige qué versión conservar.</p></div><div class="export-actions">${button('keep-local','Usar el texto de esta pestaña')}${button('load-stored','Abrir la versión guardada')}</div>`:reason==='deleted'?`<div role="alert"><strong>El cuaderno se borró desde otra pestaña.</strong><p>Esta pestaña también se vació para que nadie más vea esos textos. Lo que escribas desde ahora empieza un cuaderno nuevo.</p></div><div class="export-actions">${button('dismiss-warning','Entendido')}</div>`:`<div role="alert"><strong>El cuaderno no se pudo guardar.</strong><p>Tus textos siguen abiertos aquí. Descarga una copia antes de cerrar. ${!lock?'Este navegador no permite coordinar el guardado entre pestañas. Prueba una versión reciente de Chrome, Edge o Firefox.':''}</p></div>${button('export-json','Descargar respaldo recuperable (.json)')}`;updateSaveStatus();}
// A confirmed deletion elsewhere must not leave the previous student's texts on screen.
function wipeAfterRemoteDelete(){state=freshState();session=createSession({storage,lock,initialRaw:null});pendingImport=null;relationEdit=-1;storageBlocked=false;savePhase='saved';$('#import-file').value='';for(const d of [$('#action-dialog'),$('#import-dialog'),$('#delivery-dialog')]){if(d.open)d.close();d.innerHTML='';}$('#storage-warning')?.remove();held=null;locked=false;viewOnly=false;disown();render();storageNotice('deleted');}

const icon='<svg viewBox="0 0 24 24" aria-hidden="true" class="icon"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';
const outward='<svg viewBox="0 0 24 24" aria-hidden="true" class="icon"><path d="M6 18L18 6M6 6h12v12"/></svg>';
const exitIcon='<svg viewBox="0 0 24 24" aria-hidden="true" class="icon"><path d="M10 4H5v16h5M15 8l4 4-4 4M19 12H9"/></svg>';
// Work states read by colour, icon and label together (manual §8.3), never by colour alone.
const statusIcons={'Sin empezar':'<circle cx="12" cy="12" r="8" stroke-dasharray="2.5 3"/>','En construcción':'<path d="M5 19h4L19 9l-4-4L5 15v4z"/>','Revisado':'<circle cx="12" cy="12" r="9"/><path d="M8 12.5l2.5 2.5L16 9.5"/>','Modificado después de revisar':'<path d="M19 12a7 7 0 1 1-2-4.9"/><path d="M19 4v4h-4"/>'},statusSlug={'Sin empezar':'empty','En construcción':'draft','Revisado':'done','Modificado después de revisar':'changed','Revisión registrada':'registered'};
statusIcons['Revisión registrada']='<path d="M12 3a9 9 0 1 0 9 9"/><path d="M8.5 12l2.5 2.5 5-5"/>';
const chipInner=s=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="icon">${statusIcons[s]}</svg>${s}`;
const statusChip=(s,{key='',cls=''}={})=>`<span title="${cls==='reviewed-label'?'Estado del taller comparativo; las demás actividades están en la programación de la unidad':'Estado de este trabajo en el cuaderno; no es una calificación'}" class="status-chip ${cls}" data-status="${statusSlug[s]}"${key?` data-work-status="${key}"`:''}>${chipInner(s)}</span>`;
const link=(url,label,cls='text-link')=>url?.startsWith('./materiales/')?`<a class="${cls}" href="${escape(url)}">${escape(label)} ${icon}</a>`:`<a class="${cls}" href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} ${outward}<span class="sr-only"> (abre en otra pestaña)</span></a>`;
const note=(key,field)=>state.notes[key]?.[field]||'';
const button=(action,label,cls='button',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function toast(message,ms=5000){clearTimeout(toastTimer);$('#status').textContent=message;$('#status').classList.add('visible');toastTimer=setTimeout(()=>$('#status').classList.remove('visible'),ms);}
async function save(){
 if(locked)return false;
 if(storageBlocked){storageNotice('unavailable');return false;}
 if(['modulo','introduccion','proyecto'].includes(current.page))state.lastLocation=location.hash;
 const writer=session;pendingSaves++;updateSaveStatus();
 const result=await writer.save(state);pendingSaves--;
 // The session was replaced (deletion, import or reload) while this write waited.
 if(writer!==session){updateSaveStatus();return false;}
 if(result.ok){state.updatedAt=result.updatedAt;localSave=true;justFinished=false;if(!owned&&hasWork(state)){owned=true;lastStamp=0;markActive();}showSavedTag();if(savePhase!=='conflict'){savePhase='saved';$('#storage-warning')?.remove();}}
 else if(result.reason==='conflict'&&storedRaw()===null&&!mutationBusy){wipeAfterRemoteDelete();return false;}
 else storageNotice(result.reason);
 updateSaveStatus();return result.ok;
}

function field(key,name,label,hint='',rows=4){const id=`${key}-${name}`;return `<div class="field"><label for="${id}">${label}</label>${hint?`<p class="field-hint" id="${id}-hint">${hint}</p>`:''}<textarea id="${id}" rows="${rows}" maxlength="60000" data-note="${key}" data-field="${name}" ${locked?'readonly placeholder="Oculto en modo consulta"':''} aria-describedby="${hint?id+'-hint ':''}${id}-error">${escape(note(key,name))}</textarea><p class="field-error" id="${id}-error"></p><div class="field-footer"><span class="field-saved" data-saved-for="${id}" aria-hidden="true"></span>${name==='argument'||name==='translation'?`<span class="word-count" data-count="${id}">${count(wordCount(note(key,name)),'palabra','palabras')}</span>`:''}</div></div>`;}
function moduleStatus(m){return moduleWorkStatus(state,m);}

function progressView(m,cls=''){const p=activityProgress(state,m);return `<span class="work-progress ${cls}" data-module-progress="${m.id}"><span class="taller-progress">Taller: ${statusChip(moduleStatus(m))}</span><span class="activity-progress">Actividades: ${p.started}/${p.total} iniciadas</span></span>`;}
function weekShortcut(){return `<div class="week-shortcut"><label for="week-jump">Ir a una semana</label><select id="week-jump"><option value="">Elegir semana…</option>${weeks.map(w=>`<option value="${w.week}" ${current.week===w.week?'selected':''}>Semana ${w.week} · ${escape(w.title)}</option>`).join('')}</select></div>`;}
function renderSidebar(){const id=current.page==='modulo'?current.module:0;$('#sidebar').innerHTML=`<div class="sidebar-top"><a href="#inicio" class="smallcaps">El recorrido</a><span class="sidebar-rule"></span></div><nav aria-label="Módulos del curso"><a class="side-item ${current.page==='introduccion'?'active':''}" href="#introduccion" ${current.page==='introduccion'?'aria-current="page"':''}><span class="number">00</span><span>Antes de comparar<small>Orígenes y preguntas</small></span></a>${modules.map(m=>`<a class="side-item ${id===m.id?'active':''}" href="#modulo/${m.id}/orientar" ${id===m.id?'aria-current="page"':''}><span class="number">0${m.id}</span><span>${m.title}<small>${m.axis}</small>${locked?'':progressView(m)}</span></a>`).join('')}</nav>${weekShortcut()}<div class="sidebar-bottom"><span class="smallcaps">Tu trabajo</span><a href="#cuaderno" class="notebook-link">Mi cuaderno ${icon}</a><p>Las lecturas se conectan.<br> Tu argumento también.</p><span class="save-status" data-save-status>${savedLabel()}</span>${hasWork(state)?button('clear-notebook',exitIcon+'Terminar en este equipo','text-button finish-button'):''}</div>`;scrollHints($('#sidebar nav'));}
function resourceCard(id,compact=false){const r=resourceById[id],heading=current.page==='biblioteca'?'h2':'h3';return `<article id="recurso-${r.id}" tabindex="-1" class="resource ${compact?'compact':''}"><div class="resource-meta"><span>${escape(r.kind)} · ${escape(r.language)}</span><span class="access ${r.access==='Biblioteca'?'library-access':''}">${escape(r.access==='Gratis'?'Consulta gratuita':r.access)}</span></div><p class="author">${escape(r.author)}</p><${heading}>${escape(r.title)}</${heading}><p class="resource-place">${r.modules.map(id=>id===0?'Introducción':`M${id} · ${moduleById[id].title}`).join(' / ')}</p><p class="caption resource-role">${escape(r.audience||'Lectura común')}${r.time?' · '+escape(r.time):''}</p><p class="selection">${escape(r.selection)}</p>${r.availabilityNote?`<p class="availability-note">${escape(r.availabilityNote)}</p>`:''}${r.translator?`<p class="translator">Traducción: ${escape(r.translator)}</p>`:''}<p>${escape(r.purpose)}</p><details><summary>Edición y límites de la selección</summary><p>${escape(r.edition)}</p><p>${escape(r.limit)}</p>${r.access==='Biblioteca'?'<p>Trabaja con el ejemplar facilitado por el docente o disponible en tu biblioteca. El enlace identifica la edición; no contiene el texto completo.</p>':''}</details><div class="resource-links">${r.url?link(r.url,r.linkLabel||(r.access==='Biblioteca'?'Ver edición':r.format==='Video'?'Ver en Punkrobot':'Abrir lectura')):`<p class="caption">${r.access==='En preparación'?'Selección pendiente de incorporar.':'Selección mediante el ejemplar del docente.'}</p>`}${r.alternate?link(r.alternate,r.alternateLabel):''}${r.publisherUrl?link(r.publisherUrl,r.publisherLabel):''}</div></article>`;}
function sourceList(ids){return `<div class="resource-grid">${ids.map(id=>resourceCard(id)).join('')}</div>`;}
function header(meta,title,description){return `<div class="page-heading">${meta?`<p class="smallcaps">${meta}</p>`:''}<h1 id="page-title" tabindex="-1">${title}</h1>${description?`<p class="lead">${description}</p>`:''}</div>`;}
function schoolsView(){return `<section class="schools-section" aria-labelledby="schools-title"><p class="smallcaps">Escuelas y perspectivas</p><h2 id="schools-title">Tres maneras de plantear la comparación.</h2><p class="schools-lead">Dos tradiciones históricas y un conjunto de perspectivas críticas ayudan a situar nuestras preguntas. Estos énfasis se discuten, se cruzan y coexisten: no son tres etapas que se reemplazan ni un mapa completo de la disciplina.</p><table class="schools-table"><caption>Orientación inicial: pregunta, evidencia y límite de cada perspectiva</caption><thead><tr><th scope="col">Tradición o perspectiva</th><th scope="col">Qué pregunta</th><th scope="col">Qué evidencia busca</th><th scope="col">Qué límite reconocer</th></tr></thead><tbody>${schools.map(s=>`<tr><th scope="row"><h3>${escape(s.title)}</h3><p class="school-period">${escape(s.period)}</p><p>${escape(s.authors)}</p></th><td data-label="Qué pregunta"><strong>${escape(s.focus)}</strong><p>${escape(s.question)}</p></td><td data-label="Qué evidencia busca"><p>${escape(s.evidence)}</p></td><td data-label="Qué límite reconocer"><p>${escape(s.limit)}</p></td></tr>`).join('')}</tbody></table><div class="school-examples"><h3>Reconocer el enfoque en nuestro corpus</h3><p>Estos ejemplos anticipan módulos posteriores; puedes volver a ellos durante el curso. Los siguientes ejemplos trasladan una pregunta metodológica al curso; no clasifican a los autores literarios dentro de estas escuelas.</p>${schools.map(s=>`<details><summary>${escape(s.exampleTitle)}</summary><p>${escape(s.example)}</p><a href="${s.href}" class="text-link">Ir a ${escape(s.next)} ${icon}</a></details>`).join('')}</div><details class="schools-sources"><summary>Referencias de esta orientación</summary><p>Síntesis docente. Para el panorama histórico: Irlanda Villegas, «De Madame de Staël a Saussy…», pp. 13–14. Para la ampliación del campo asociada a Remak: José Luis Martínez Suárez, presentación de <em>¿Qué es literatura comparada? Impresiones actuales</em>, pp. 7–8. Los nombres orientan debates; no sustituyen la lectura de cada propuesta.</p><p>${link('https://www.uv.mx/bdh/files/2014/09/Libro-Literatura-comparada-II.pdf#page=15','Villegas: contexto histórico')} · ${link('https://www.uv.mx/bdh/files/2014/08/Libro-1-literatura-comparada.pdf#page=9','Martínez Suárez: presentación')}</p><p>Para las diferencias entre heterogeneidad y entre-lugar: ${link(resourceById.cornejo.url,'Cornejo Polar, artículo de 1978')} · ${link(resourceById.santiago.url,'Santiago, entrevista de 2014')}. Se conservan como preparación docente; el recorrido común incorpora Rivera Cusicanqui y oralitura contemporánea.</p><p>Hitos bibliográficos: René Wellek, «The Crisis of Comparative Literature», conferencia de 1958, publicada en 1959; Henry H. H. Remak, «Comparative Literature, Its Definition and Function», 1961. ${link('https://elibrary.wayne.edu/record%3D3033568','Ficha bibliográfica del volumen de Remak')}. Esta ficha identifica el libro; no ofrece el capítulo completo.</p></details></section>`;}
function placeName(hash){const week=String(hash).match(/^#semana\/(\d+)$/)?.[1];if(week)return 'Semana '+week+' · '+(weeks.find(w=>w.week===Number(week))?.title||'Recorrido');const [,page,mod,step]=String(hash).match(/^#(\w+)(?:\/(\d)\/(\w+))?/)||[];if(page==='modulo'&&moduleById[mod])return `${moduleById[mod].title} · ${moduleSteps(Number(mod)).find(s=>s[0]===step)?.[1]||'Situar'}`;return page==='proyecto'?'Ensayo final':'Antes de comparar';}
function sinceLabel(iso){if(!iso)return '';const minutes=Math.round((Date.now()-Date.parse(iso))/60000),rtf=new Intl.RelativeTimeFormat('es',{numeric:'auto'});if(minutes<1)return 'hace un momento';if(minutes<60)return rtf.format(-minutes,'minute');if(minutes<1440)return rtf.format(-Math.round(minutes/60),'hour');return 'el '+new Date(iso).toLocaleDateString('es',{day:'numeric',month:'long'});}
// On a shared computer the stored notebook may belong to someone else: its notes stay hidden until someone
// confirms it is theirs, and again after 20 idle minutes (lab turnover).
const IDLE_LOCK=20*60000;let owned=false,locked=false,viewOnly=false,resumeAt=null,held=null,lastActive=Date.now(),lastStamp=0;
function markActive(){lastActive=Date.now();if(!locked&&owned&&lastActive-lastStamp>15000){lastStamp=lastActive;try{sessionStorage.setItem('lc-owner',String(lastActive));}catch{}}}
function lockNotebook(show=true){if(locked||!hasWork(state))return;resumeAt={hash:location.hash,y:window.scrollY,id:document.activeElement?.id||''};held=state;state=freshState();locked=true;owned=false;try{sessionStorage.removeItem('lc-owner');}catch{}for(const d of [$('#action-dialog'),$('#import-dialog'),$('#delivery-dialog')])if(d.open)d.close();cleanupDeliveryPrint();if(show)render();}
function unlockNotebook(){if(locked){state=held;held=null;locked=false;viewOnly=false;}owned=true;lastStamp=0;markActive();}
function disown(){owned=false;try{sessionStorage.removeItem('lc-owner');}catch{}}
function ownerCheck(){let stamp=0;try{stamp=Number(sessionStorage.getItem('lc-owner'))||0;}catch{}if(!hasWork(state)){disown();return;}if(Date.now()-stamp>IDLE_LOCK)lockNotebook(false);else{owned=true;markActive();}}
function lockMeta(){const src=held||state,when=sinceLabel(src.updatedAt);return `Última edición: ${escape(placeName(src.lastLocation))}${when?' · '+when:''}.`;}
function destinationName(){return {cuaderno:'Mi cuaderno',proyecto:'Ensayo final',introduccion:'Antes de comparar'}[current.page]||placeName(location.hash);}
function consultBar(){return `<section class="consult-bar" aria-label="Modo consulta"><p><strong>Modo consulta.</strong> El cuaderno guardado sigue oculto y aquí no se guarda nada.</p><div class="export-actions">${button('owner-ok','Es mío, continuar','button')}${button('not-mine','No es mío: empezar de cero','button')}</div></section>`;}
function finishedCard(){return `<section class="owner-card" aria-labelledby="done-title"><h2 id="done-title" tabindex="-1">Cuaderno vaciado</h2><p>Este navegador ya no guarda tu trabajo. Puedes cerrar el navegador o dejar el equipo al siguiente estudiante.</p><div class="export-actions"><a href="#introduccion" class="button">Empezar el recorrido ${icon}</a></div></section>`;}
function homeLockCard(){return `<section class="owner-card" aria-labelledby="owner-title"><h2 id="owner-title">¿Es tuyo este cuaderno?</h2><p data-lock-meta>${lockMeta()}</p><div class="export-actions">${button('owner-ok','Es mío, continuar','button')}${viewOnly?'<a class="button" href="#introduccion">Empezar a leer</a>':button('consult','Solo consultar')}${button('not-mine','No es mío: empezar de cero')}</div><p class="caption">${viewOnly?'Modo consulta: el cuaderno guardado sigue oculto y no se guarda nada.':'Sus notas permanecen ocultas hasta que confirmes que es tuyo.'}</p></section>`;}
function lockView(){return `${header('','¿Es tuyo este cuaderno?','Hay un cuaderno guardado en este navegador. Sus notas permanecen ocultas hasta que confirmes que es tuyo.')}<section class="owner-card owner-lock" aria-label="Propiedad del cuaderno"><p><strong>Ibas a: ${escape(destinationName())}.</strong></p><p data-lock-meta>${lockMeta()}</p><div class="export-actions">${button('owner-ok','Es mío, continuar','button')}${viewOnly?'<a class="button" href="#introduccion">Seguir consultando</a>':button('consult','Solo consultar')}${button('not-mine','No es mío: empezar de cero')}</div><p class="caption">«Solo consultar» muestra los módulos sin abrir ni borrar el cuaderno guardado; para escribir, confirma primero.</p><p class="caption">Si no es tuyo, empieza con un cuaderno vacío: nadie verá el trabajo de otra persona.</p></section>`;}
function ownerCard(){const src=held||state;return `<section class="owner-card" aria-labelledby="owner-title"><h2 id="owner-title">Hay un cuaderno en este navegador</h2><p data-lock-meta>${lockMeta()}</p><div class="export-actions"><a href="${escape(src.lastLocation)}" class="button primary" data-owner-ok>Retomar mi trabajo ${icon}</a>${button('clear-notebook',exitIcon+'Terminar en este equipo')}</div><p class="caption">En un equipo compartido, vacía el cuaderno al terminar para que el siguiente estudiante empiece de cero.</p></section>`;}
function home(){return `<div class="home-intro"><div class="home-copy"><h1>Leer entre<br> las literaturas<span class="red-dot">.</span></h1><p class="lead">Construye una relación.<br> Sostén una lectura.<br> Vuelve a pensarla.</p>${locked?homeLockCard():justFinished?finishedCard():hasWork(state)?ownerCard():`<a href="#introduccion" class="button primary">Empezar el recorrido ${icon}</a>`}<p class="home-footnote">Un seminario de lectura, comparación y escritura.</p></div><div class="opening-question"><span class="smallcaps">La pregunta de partida</span><p>¿Qué se vuelve visible<br> cuando leemos<br> <em>una obra junto a otra?</em></p><div class="relation-line"><span>Obra A</span><span aria-hidden="true">⟷</span><span>Obra B</span></div><span class="caption">La relación se construye con evidencia.</span></div></div><section class="path-section"><div class="section-heading"><h2>Cuatro problemas.<br> Un argumento en construcción.</h2><span class="smallcaps">16 semanas · 4 módulos</span></div><div class="course-rows">${modules.map(m=>`<a href="#modulo/${m.id}/orientar" class="course-row"><span class="number">0${m.id}</span><span><h3>${m.title}</h3><span class="muted">${m.axis}</span>${locked?'':progressView(m)}</span><p>${m.question}</p>${icon}</a>`).join('')}</div></section>${evaluationView()}<section class="blue-band"><div><span class="smallcaps">Del cuaderno al ensayo final</span><h2>Tu primera hipótesis<br> no tiene que ser la última.</h2><p>Conserva indicios, contrasta objeciones y da forma a un ensayo comparativo.</p></div><a href="#proyecto" class="button light">Abrir mi proyecto ${icon}</a></section><section class="how-section"><h2>Una forma de trabajar</h2><div class="how-grid"><div><span class="number">01 / ANTES</span><h3>Leer y situar</h3><p>Abre una selección delimitada. Registra una hipótesis y localiza un indicio.</p></div><div><span class="number">02 / EN CLASE</span><h3>Confrontar evidencia</h3><p>Compara formas, contextos y una lectura rival. Declara los límites de la relación.</p></div><div><span class="number">03 / DESPUÉS</span><h3>Argumentar y revisar</h3><p>Explica qué cambió en tu interpretación. Incorpora el trabajo a tu ensayo final.</p></div></div></section>`;}
function intro(){return `${header('00 / Introducción','Antes de comparar','Una historia breve de las preguntas que hacen posible este recorrido.')}<div class="intro-grid"><article class="reading"><p class="intro-emphasis">La literatura comparada no empieza con una lista de parecidos. Empieza cuando hacemos de una relación un problema de lectura.</p><p>Esta entrada distingue dos historias conectadas: la de las prácticas de intercambio entre literaturas y la de la disciplina que las estudia. Sus fronteras han sido discutidas desde su formación.</p><div class="timeline">${history.map((h,i)=>`<section><span class="timeline-index">0${i+1}</span><div><p class="smallcaps">${h.label}</p><h2>${h.title}</h2><p>${h.text}</p></div></section>`).join('')}</div><p class="source-note">Síntesis didáctica propia a partir de Villegas, Culler, Crolla, Cornejo Polar y la entrevista a Santiago. ${link('https://www.uv.mx/bdh/files/2014/09/Libro-Literatura-comparada-II.pdf#page=15','Consultar la referencia histórica')} · ${link('https://www.acla.org/about','Historia institucional de ACLA')}</p></article><aside class="margin-note" aria-label="Para llevar al curso"><span class="smallcaps">Para llevar al curso</span><h3>Cuatro distinciones útiles</h3><dl><dt>Comparación / influencia</dt><dd>Una relación propuesta no prueba un contacto histórico.</dd><dt>Obra / edición</dt><dd>Leemos un testimonio situado: importa quién edita y traduce.</dd><dt>Tema / forma</dt><dd>La coincidencia temática no explica cómo está construida una obra.</dd><dt>Interpretación / evidencia</dt><dd>Una hipótesis necesita pasajes y un razonamiento explícito.</dd></dl></aside></div>${schoolsView()}<section class="exercise"><div class="section-heading"><h2>¿Qué tipo de relación estás construyendo?</h2><span class="smallcaps">Exploración inicial</span></div><p>Abre cada caso y contrasta la orientación con tu propia respuesta.</p><div class="diagnostic">${diagnostic.map(d=>`<details><summary>${d.title}</summary><p>${d.answer}</p></details>`).join('')}</div><p class="save-line" data-save-status>${savedLabel()}</p>${field('intro','intro','Mi primera pregunta comparativa','Propón dos obras, un aspecto observable y un límite de la comparación.',3)}<a href="#semana/1" class="button primary">Empezar la semana 1 · Comparar y elegir ${icon}</a></section>`;}
function lenses(m){return `<aside class="lenses" aria-label="Lentes de lectura"><h2>Lentes de lectura</h2>${m.lenses.map((l,i)=>`<details ${i===0?'open':''}><summary>${l[0]}</summary><p>${l[1]}</p><span class="caption">${l[2]}</span></details>`).join('')}${glossaryLinks(m.id)}<div class="margin-callout"><span class="smallcaps">Una pregunta más</span><p>${m.review}</p></div><a href="#cuaderno" class="text-link">Volver a mis notas ${icon}</a></aside>`;}
function routePicker(m){if(Object.keys(m.routes).length<2)return '';const chosen=m.routes[state.routes[m.id]]?state.routes[m.id]:'A';const picker=`<section class="route-picker" aria-label="${m.both?'Talleres del módulo':'Elección de ruta'}"><div class="route-intro"><strong>${m.both?'Dos talleres conectados':'Elige una ruta para este taller'}</strong><p>${m.both?'Trabaja Cervantes–Borges; después, amplía la comparación a memoria y medios.':'Mismo objetivo y criterios. Puedes cambiar de ruta sin perder tus notas.'}</p></div><div class="route-buttons">${Object.entries(m.routes).map(([key,r])=>`<button type="button" data-action="route" data-route="${key}" aria-pressed="${chosen===key}" class="route-button"><span class="smallcaps">${m.both?'Taller':'Ruta'} ${key}</span><span>${r.label}</span><span class="route-choice">${chosen===key?'En la mesa':m.both?'Abrir este taller':'Abrir esta ruta'}</span>${statusChip(keyStatus(routeKey(m,key)),{key:routeKey(m,key),cls:'route-status'})}</button>`).join('')}</div></section>`;if(current.step==='leer')return picker;return `<details class="route-compact"><summary><span class="smallcaps">${m.both?'Taller':'Ruta'} ${chosen}</span><span class="route-compact-label">${m.routes[chosen].label}</span><span class="route-compact-action">${m.both?'Cambiar de taller':'Cambiar de ruta'}</span></summary>${picker}</details>`;}
function comparison(m,key,r){return `<div class="work-heading"><span class="smallcaps">${m.both?'Taller':'Ruta'} ${(Object.entries(m.routes).find(([,r])=>r.noteKey===key)?.[0]||'A')} / ${r.label}</span><h2>${r.question}</h2><p>Abre las lecturas, elige pasajes y registra su procedencia. Puedes pegar fragmentos de tu ejemplar para analizarlos en tu cuaderno.</p></div>${field(key,'hypothesis','Mi hipótesis inicial','Conserva aquí tu primera formulación. Al final escribirás una versión revisada.',3)}<div class="comparison-pair">${r.texts.map((id,i)=>{const s=i?'B':'A',res=resourceById[id];return `<section class="comparison-document"><span class="smallcaps">Documento ${s}</span><h3>${escape(res.title)}</h3><p class="author">${escape(res.author)}</p>${res.translator?`<p class="caption">Traducción: ${escape(res.translator)}</p>`:''}<p class="selection">${escape(res.selection)}</p>${link(res.url,res.access==='Biblioteca'?'Ver edición':res.format==='Video'?'Ver el cortometraje':'Abrir lectura')} ${res.alternate?link(res.alternate,res.alternateLabel):''}<p class="reading-prompt">${r.prompts[i]}</p>${field(key,'evidence'+s,'Pasaje o evidencia '+s,'Cita o describe el indicio. Distingue cita y comentario.',5)}${field(key,'locator'+s,'Fuente y localizador '+s,res.format==='Video'?'Productora, fuente y minuto del cortometraje.':'Edición, página o párrafo del texto.',2)}</section>`;}).join('')}</div><div class="contrast-bottom">${promptInArgument.has(key)?'':`<p class="serif">${r.prompts[2]}</p>`}${field(key,'difference','La diferencia que importa','Explica qué cambia entre los objetos y por qué no debemos equipararlos.',3)}</div><div class="next-bar"><span>Del indicio al argumento</span><a class="button primary" href="#modulo/${m.id}/argumentar">Construir mi argumento ${icon}</a></div>`;}
function translation(){return `<section class="translation-workshop" id="traduccion"><div class="section-heading"><div><p class="smallcaps">Taller común · 40 minutos orientativos</p><h2>Un puerto,<br> <em>dos traducciones.</em></h2></div><span class="caption">Baudelaire · Poema en prosa XLI</span></div><p class="lead">La misma escena, decisiones diferentes. Lee el poema completo en las versiones de Casal y Díez-Canedo; después coteja lugares precisos del francés.</p><div class="translation-sources">${['baudelaire','casal','diez'].map(id=>{const r=resourceById[id];return `<div id="recurso-${id}" tabindex="-1"><span class="smallcaps">${r.language}</span><h3>${r.translator||'Original de 1869'}</h3>${link(r.url,'Leer el poema')}<p class="caption">${r.selection}</p></div>`;}).join('')}</div>${field('3-traduccion','initialTranslation','Antes de cotejar','¿Qué escena y qué observador imaginas en cada versión?',3)}<details class="translation-collation"><summary>Desplegar cuatro lugares para el cotejo</summary><div class="table-scroll"><table><caption>Testimonios editoriales fijados en la biblioteca del curso</caption><thead><tr><th>Francés</th><th>Casal</th><th>Díez-Canedo</th><th>Pregunta</th></tr></thead><tbody>${translationRows.map(r=>`<tr><td lang="fr">${r.original}</td><td>${r.casal}</td><td>${r.diez}</td><td>${r.question}</td></tr>`).join('')}</tbody></table></div><p>No atribuyas una intención al traductor sólo por una diferencia. Si no dominas francés, distingue lo que observas en español de lo que puedes sostener con apoyo del original y del docente.</p></details>${alertHtml(3)}${field('3-traduccion','translation','Comentario de traducción','Elige tres diferencias. Explica sus efectos en escena, ritmo o posición del observador y formula una duda para el cotejo del francés. Extensión final: 400–500 palabras; inicia el comentario en aula y complétalo en el trabajo autónomo.',7)}<p class="caption">Secuencia sugerida: lectura, 8 min · cotejo, 15 min · discusión, 7 min · comentario, 10 min.</p></section>`;}
function film(){return `<section class="film-section"><div class="section-heading"><h2>Ver también es leer</h2><span class="smallcaps">Historia de un oso · 2014</span></div><p class="lead">Antes de reproducir: ¿quién organiza lo que vemos y cómo cambia nuestra relación con ese relato?</p><div id="video-slot" class="video-slot"><div class="video-placeholder"><h3>Historia de un oso</h3><p>Gabriel Osorio / Punkrobot<br> 10 min 30 s · Sin diálogos</p>${link(resourceById.oso.url,'Ver en el canal de Punkrobot','button light')}<span class="caption">Se abre en otra pestaña. Tus notas permanecen aquí.</span></div></div><details class="viewing-guide"><summary>Guía de observación y descripción narrativa</summary><p>Observa tres niveles: el oso que prepara y muestra su mecanismo, la historia de los personajes del teatrillo y el público que la contempla. Anota cómo se relacionan el presente de la exhibición y el pasado representado.</p><p>El corto muestra a un oso que lleva a la calle un teatrillo mecánico. En él, una familia es separada y un oso es obligado a actuar en un circo. La narración del mecanismo imagina una vuelta al hogar. El contraste con el presente de quien lo exhibe abre preguntas sobre ausencia, recuerdo y deseo.</p><p>Esta orientación escrita no sustituye una audiodescripción sincronizada. El recurso no tiene diálogos; escucha también música, ruidos y silencios, y explica qué aportan al sentido.</p></details></section>`;}
function moduleSteps(id){return id===3?[...steps.slice(0,3),['traduccion','Traducir'],...steps.slice(3)]:steps;}
function modulePage(){const m=moduleById[current.module],route=m.routes[state.routes[m.id]]?state.routes[m.id]:'A',r=m.routes[route],key=routeKey(m,route);
 let content='';
 if(current.step==='orientar')content=`<div class="deliverable"><h2>Lo que construirás</h2><h3>${m.outcome}</h3><p>${m.product}</p></div>${locked?'':progressView(m)}${teachingPlan(m,field)}<details class="concept-guide"><summary>Conceptos para este recorrido</summary><div class="reading">${m.sections.map(s=>`<section><h2>${s[0]}</h2><p>${s[1]}</p></section>`).join('')}<p class="source-note">Orientación didáctica propia. Contrasta estas herramientas con las selecciones de ${m.theory.map(id=>resourceById[id].author).join(', ')} en Leer.</p></div></details><a href="#modulo/${m.id}/leer" class="button primary">Abrir las lecturas ${icon}</a>`;
 if(current.step==='leer')content=`${routePicker(m)}<div class="section-heading"><h2>Lecturas de ${Object.keys(m.routes).length===1||m.both?'este taller':'tu ruta'}</h2><span class="smallcaps">${r.label}</span></div>${sourceList(r.texts)}${m.common?.length?`<div class="section-heading subsection"><h2>Otras lecturas comunes de la unidad</h2></div>${sourceList(m.common)}`:''}<div class="section-heading subsection"><h2>Herramientas teóricas</h2><span class="smallcaps">Base común</span></div>${sourceList(m.theory)}${m.support?.length?`<details class="teacher-resources"><summary>Preparación docente y alternativas de sustitución</summary><p>Estos materiales orientan la preparación o permiten sustituir una lectura con la misma función y carga. No se suman a las lecturas comunes.</p>${sourceList(m.support)}</details>`:''}${m.id===3?'<p class="inline-note">El taller de traducción tiene tres textos breves propios. Encontrarás sus enlaces y el cotejo en Traducir.</p>':''}<a class="button primary" href="#modulo/${m.id}/comparar">Llevar a la mesa ${icon}</a>`;
 if(current.step==='comparar')content=`${routePicker(m)}${m.id===4&&route==='B'?film():''}${comparison(m,key,r)}`;
 if(current.step==='traduccion')content=translation()+`<div class="translation-next"><p>El trabajo de recepción corresponde a la semana 10. Después del cotejo y el comentario, continúa con el contraste de métodos de la semana 12.</p><a href="#semana/12" class="button primary">Continuar con la semana 12 ${icon}</a>${activityLinks(m,'Consultar las actividades del módulo')}<a class="button" href="#modulo/3/orientar" data-goto-field="unit-program-3">Volver a la programación de la unidad ${icon}</a></div>`;
 if(current.step==='argumentar')content=`${routePicker(m)}<p class="smallcaps">Semana ${r.workshop.week} · ${escape(r.workshop.title)}</p><h2>Un argumento que pueda discutirse</h2><p class="lead">${escape(r.workshop.text)}</p>${promptInArgument.has(key)?`<p class="serif">${r.prompts[2]}</p>`:''}${alertHtml(m.id)}${field(key,'objection','La objeción más exigente','Formula otra lectura y señala el pasaje que la vuelve plausible.',4)}${field(key,'argument',m.id===3?'Mi interpretación comparada':m.id===4&&route==='B'?'Mi contraste entre medios':'Mi ficha comparativa',r.workshop.text,10)}${activityLinks(m,'Otros productos de la unidad')}<div class="next-bar"><span>Una lectura abierta a revisión</span><a class="button primary" href="#modulo/${m.id}/revisar">Revisar mi hipótesis ${icon}</a></div>`;
 if(current.step==='revisar')content=`${routePicker(m)}<h2>Volver a pensar la relación</h2><p class="lead">${m.review}</p><div class="revision-original"><span class="smallcaps">Tu hipótesis inicial</span><p class="preserve serif">${escape(note(key,'hypothesis'))||(locked?'Oculto en modo consulta.':'Todavía no has registrado una hipótesis. Puedes hacerlo en Contrastar.')}</p></div>${field(key,'revision','Mi hipótesis revisada','Escribe la formulación que sostienes después del contraste.',4)}${field(key,'revisionReason','Qué cambió y por qué','Nombra una evidencia o una objeción decisiva. Si mantienes tu hipótesis, explica cómo la has puesto a prueba.',4)}<div class="review-criteria"><h3>Antes de cerrar tu revisión</h3><ul><li>¿Cada afirmación central se apoya en un pasaje localizable?</li><li>¿La comparación atiende a la forma y a las diferencias de contexto?</li><li>¿Respondes a una objeción sin descalificarla?</li><li>¿Distingues lo documentado de lo que propones interpretar?</li></ul></div><div class="review-actions">${locked?'':`${progressView(m)}<p class="work-status">Este taller: ${statusChip(keyStatus(key),{key})}</p>`}${!locked&&moduleMissing(m,route)?`<p class="review-pending">${m.id===3?'El comentario de traducción se realiza en la semana 11:':'El recorrido del módulo incluye también:'} ${moduleMissing(m,route)}.</p>`:''}<div id="review-error" class="field-error" role="alert"></div>${locked?'':reviewButton(key)}<a class="button" href="#proyecto">Ver mi ensayo final ${icon}</a></div>${activityLinks(m,'Continúa las actividades de la unidad')}<a class="button" href="#modulo/${m.id}/orientar" data-goto-field="unit-program-${m.id}">Volver a la programación de la unidad ${icon}</a>${nextWorkshop(m,route)}${hasWork(state)?`<div class="finish-row">${button('clear-notebook',exitIcon+'Terminar en este equipo','button')}<p class="caption">Al acabar en un computador compartido, vacía el cuaderno para el siguiente estudiante.</p></div>`:''}<p class="caption">Este estado registra la revisión del taller comparativo. Las otras actividades están en Situar; no acredita toda la unidad ni es una calificación o entrega al docente.</p>`;
 return `<div class="${current.step==='orientar'?'':'compact-heading'}">${header(`0${m.id} / ${m.axis} <span class="meta-divider">·</span> ${m.weeks}`,m.title,m.question)}</div><nav class="step-nav" aria-label="Espacios de trabajo del módulo">${stepLinks(m,key)}</nav>${m.id===3?'<p class="workshop-navigation-note">El taller Carrington–Bierce se trabaja en la semana 9: Contrastar, Argumentar y Revisar. Recepción corresponde a la 10 y Traducir a la 11; sigue las semanas para organizar el trabajo.</p>':''}${['orientar','leer'].includes(current.step)?'':`<p class="save-line" data-save-status>${savedLabel()}</p>`}<div class="module-layout ${current.step==='argumentar'?'writing-layout':''}"><article class="module-body">${current.step==='orientar'?`<p class="opening-paragraph">${m.intro}</p>`:''}${content}</article>${current.step==='argumentar'?evidenceDesk(key,r,m):lenses(m)}</div>`;
}
function library(){return `${header('El corpus','Biblioteca de relaciones','Cada lectura tiene un lugar en el recorrido. Aquí encontrarás su edición, el fragmento de trabajo y el propósito del contraste.')}<div class="library-filters"><div class="search-field"><label for="library-search">Buscar en el corpus</label><input type="search" id="library-search" placeholder="Autor, título, traductor o concepto…"></div><div><label for="filter-module">Módulo</label><select id="filter-module"><option value="">Todos</option><option value="0">00 · Introducción</option>${modules.map(m=>`<option value="${m.id}">0${m.id} · ${m.title}</option>`).join('')}</select></div><div><label for="filter-kind">Material</label><select id="filter-kind"><option value="">Todos</option>${[...new Set(resources.map(r=>r.kind))].map(t=>`<option>${t}</option>`).join('')}</select></div><div><label for="filter-access">Acceso</label><select id="filter-access"><option value="">Todos</option>${[...new Set(resources.map(r=>r.access))].map(a=>`<option>${escape(a)}</option>`).join('')}</select></div></div><div class="library-scope"><label for="filter-audience">Selección de materiales</label><select id="filter-audience"><option value="Lectura común">Lecturas comunes del curso</option><option value="">Todos los materiales</option><option value="Preparación docente">Preparación docente</option><option value="Alternativa de sustitución">Alternativas de sustitución</option></select></div><div class="library-count"><span id="result-count" role="status">${resources.filter(r=>r.audience==='Lectura común').length} materiales</span>${button('reset-filters','Restablecer filtros','text-button')}</div><div id="library-results" class="resource-grid library-grid">${resources.filter(r=>r.audience==='Lectura común').map(r=>resourceCard(r.id)).join('')}</div><p class="source-note">Selecciones conforme a la planificación revisada del 11 de octubre de 2026. Las fichas distinguen acceso al texto, referencia editorial y material pendiente. Consulta gratuita no implica permiso para republicar. Las lecturas de biblioteca se consultan en el ejemplar que facilite el docente o en tu biblioteca.</p>`;}
function filterLibrary(){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalize($('#library-search').value),mod=$('#filter-module').value,kind=$('#filter-kind').value,access=$('#filter-access').value,audience=$('#filter-audience').value;const found=resources.filter(r=>(!audience||r.audience===audience)&&(!mod||r.modules.includes(Number(mod)))&&(!kind||r.kind===kind)&&(!access||r.access===access)&&normalize([r.author,r.title,r.translator,r.purpose,r.language].join(' ')).includes(q));$('#result-count').textContent=`${found.length} ${found.length===1?'material':'materiales'}${mod?' · '+(mod==='0'?'Introducción':moduleById[mod].title):''}`;$('#library-results').innerHTML=found.length?found.map(r=>resourceCard(r.id)).join(''):'<div class="empty-state"><h2>No hay coincidencias</h2><p>Prueba otro autor, título o combinación de filtros.</p></div>';}
function projectMilestones(){return `<section class="essay-milestones"><h2>Del problema a la entrega</h2><p>Cuatro hitos del recorrido. Puedes revisar las decisiones anteriores mientras avanzas.</p><ol>${Object.entries(essayMilestones).map(([week,m])=>`<li><span class="caption">Semana ${week}</span><h3>${escape(m.title)}</h3><p>${escape(m.description)}</p><a href="#proyecto" data-goto-field="${m.field}" class="text-link">Trabajar este hito ${icon}</a> · <a href="#semana/${week}">Ver la semana</a></li>`).join('')}</ol></section>`;}
function project(){const options=relationOptions();return `${header('Proyecto integrador','Ensayo final','Una tesis comparativa sustentada en dos objetos del corpus, una consigna didáctica y una defensa individual.')}<p class="save-line" data-save-status>${savedLabel()}</p><section class="project-start"><p class="lead">Escribe un ensayo individual de 1500–1800 palabras sobre dos objetos del corpus común. Justifica la relación, analiza pasajes, contextualiza mediaciones y responde una objeción. La consigna didáctica, referencias y anexos se presentan por separado.</p>${projectMilestones()}<details class="project-stages-fold"><summary>Recuperar el recorrido por módulos</summary><div class="project-stages">${modules.map(m=>`<a href="#modulo/${m.id}/revisar"><span class="number">0${m.id}</span><span>${m.outcome}</span>${progressView(m,'stage-state')}</a>`).join('')}</div>${projectSynthesis()}${projectWork()}</details></section>${field('ensayo','title','Título de mi ensayo final','Haz visible tu problema comparativo.',2)}${field('ensayo','question','Pregunta que organiza el proyecto','Delimita dos objetos y el alcance de la relación.',3)}${field('ensayo','corpus','Corpus y ediciones','Registra textos, versiones, traductores, fragmentos y razones de la selección.',4)}${field('ensayo','method','Esquema argumental y decisiones del método','Tesis provisional, orden del argumento y tres nudos de evidencia con su función. Explica el criterio comparativo y un límite.',5)}<section class="essay-writing" aria-label="Mesa de escritura"><div class="essay-writing-main">${essayRubric()}${field('ensayo','argument','Borrador del ensayo','1500–1800 palabras. Puedes insertar un pasaje desde el panel y desarrollar su interpretación. Para una cita sangrada al imprimir, comienza su párrafo con > y sepáralo con una línea en blanco.',20)}</div>${projectDesk(state)}</section><section class="relations-section"><h2>Cartografía de relaciones y circulación</h2><p>Registra un vínculo y sus mediadores. Las posiciones del dibujo siguen tu registro; las asimetrías deben explicarse con evidencia.</p><form id="relation-form" novalidate><div class="relation-inputs"><div><label for="relation-from">Obra de partida</label><select id="relation-from" aria-describedby="relation-error">${options}</select></div><div><label for="relation-to">Obra en relación</label><select id="relation-to" aria-describedby="relation-error">${options}</select></div></div><div><label for="relation-type">Tipo de vínculo</label><select id="relation-type"><option value="propuesta">Comparación propuesta</option><option value="documentada">Relación documentada</option></select></div><details class="mediation-fields"><summary>Registrar mediador, fecha y medio</summary><p class="caption">Completa solo los datos que puedes documentar. El texto de evidencia conserva la fuente y el alcance.</p><div class="relation-inputs"><div><label for="relation-mediator">Mediador o cadena de mediación</label><input id="relation-mediator" maxlength="2000" placeholder="Traductor, revista, editorial…"></div><div><label for="relation-date">Fecha o intervalo documentado</label><input id="relation-date" maxlength="2000" placeholder="Con la precisión de la fuente"></div><div><label for="relation-medium">Medio y circuito</label><input id="relation-medium" maxlength="2000" placeholder="Antología, prensa, archivo…"></div></div></details><div class="field"><label for="relation-evidence">Evidencia, fuente y límite</label><textarea id="relation-evidence" aria-describedby="relation-error" required maxlength="10000" rows="3" placeholder="Fuente, localizador, relación y alcance comprobable."></textarea></div><div class="export-actions"><button class="button" type="submit" id="relation-submit">Añadir relación ${icon}</button>${button('cancel-relation','Cancelar edición','text-button','hidden')}</div><p id="relation-error" role="alert"></p></form><div id="relations-list">${relationsView()}</div></section>${field('ensayo','mediation','Consigna didáctica del ensayo','Define público, objetivo, pregunta, dos pasajes, consigna, evidencia esperada y criterio de discusión.',8)}${field('ensayo','credits','Referencias y atribuciones','Identifica ediciones, traductores y materiales citados. Revisa los localizadores insertados.',4)}${field('ensayo','defense','Guion de defensa oral','4 minutos: problema y tesis; dos evidencias decisivas; objeción, respuesta y límite. Reserva la pregunta de 1 minuto prevista para el cierre.',5)}${field('ensayo','selfAssessment','Autoevaluación con la rúbrica','Para cada criterio del ensayo, identifica un pasaje de tu escrito que lo cumpla y una mejora pendiente. Puedes incluir esta autoevaluación en la entrega.',5)}${field('ensayo','reflection','Reflexión final','¿Qué cambió en tu manera de comparar? Identifica una revisión decisiva y una pregunta abierta.',4)}<section class="delivery-start"><h2>Preparar mi entrega</h2><p>Revisa ensayo, referencias y consigna. Elige qué anexos compartir antes de imprimir o guardar como PDF.</p>${field('ensayo','student','Nombre del estudiante','Dato de la portada del dossier.',1)}${field('ensayo','deliveryDate','Fecha de entrega','Escribe la fecha que debe aparecer en la portada.',1)}<div class="export-actions">${button('prepare-delivery','Preparar entrega / PDF '+icon,'button primary')}${button('export-json','Guardar respaldo recuperable (.json)')}${button('export-md','Descargar cuaderno en texto (.md)')}</div><p class="caption">El PDF sirve para entregar. El JSON permite recuperar y continuar el trabajo en otro navegador o equipo.</p></section>${evaluationView()}`;}
function essayRubric(){return `<details class="essay-rubric"><summary>Criterios del ensayo · consultar antes de escribir</summary><p>Estos porcentajes corresponden a los criterios del escrito.</p>${rubric.map(r=>`<div class="rubric-row"><div><h3>${r[0]}</h3><span class="number">${r[1]}</span></div><p>${r[2]}</p></div>`).join('')}<p>Una interpretación bien sustentada puede discrepar de la lectura docente.</p></details>`;}
function relationsView(){return (state.relations.length?relationDiagram(state.relations)+state.relations.map((r,i)=>`<article class="relation-item" id="relation-${i}"><span class="smallcaps">${r.type==='documentada'?'Relación documentada':'Comparación propuesta'} · ${String(i+1).padStart(2,'0')}</span><h3>${escape(r.from)} ${icon} ${escape(r.to)}</h3><p class="caption">${[r.mediator&&'Mediación: '+escape(r.mediator),r.date&&'Fecha: '+escape(r.date),r.medium&&'Medio: '+escape(r.medium)].filter(Boolean).join(' · ')}</p><p class="preserve">${escape(r.evidence)}</p><div class="export-actions">${button('edit-relation','Editar relación','text-button',`data-index="${i}" aria-label="Editar relación ${i+1}"`)}${button('delete-relation','Eliminar relación','text-button',`data-index="${i}" aria-label="Eliminar relación ${i+1}"`)}</div></article>`).join(''):'<p class="empty-caption">Todavía no has añadido relaciones. Empieza con dos obras y un vínculo que puedas explicar.</p>');}
function relationOptions(){const chosen=resources.filter(r=>r.kind!=='Teoría'&&r.audience==='Lectura común');return '<option value="">Selecciona una obra…</option>'+modules.map(m=>`<optgroup label="${escape(m.title)}">${chosen.filter(r=>r.modules[0]===m.id).map(r=>`<option value="${escape(r.title)}">${escape(r.author+' · '+r.title)}</option>`).join('')}</optgroup>`).join('');}
const promptInArgument=new Set(['3-hermeneutica']);
function evidenceDesk(key,r,m){return `<aside class="evidence-desk" aria-label="Evidencias para argumentar"><details ${matchMedia('(min-width: 981px)').matches?'open':''}><summary>Mi hipótesis y mis evidencias</summary><div class="evidence-content"><h3>Hipótesis inicial</h3><p class="preserve">${escape(note(key,'hypothesis'))||(locked?'Oculto en modo consulta.':'Registra tu hipótesis en Contrastar.')}</p>${['A','B'].map((x,i)=>`<section><span class="smallcaps">Documento ${x}</span><h3>${escape(resourceById[r.texts[i]].title)}</h3><p class="preserve evidence-passage">${escape(note(key,'evidence'+x))||(locked?'Oculto en modo consulta.':'Aún no has seleccionado una evidencia.')}</p><p class="caption preserve">${escape(note(key,'locator'+x))||(locked?'':'Falta el localizador.')}</p>${link(resourceById[r.texts[i]].url,'Consultar fuente')}</section>`).join('')}<h3>Diferencia relevante</h3><p class="preserve">${escape(note(key,'difference'))||(locked?'Oculto en modo consulta.':'¿Qué diferencia vuelve pertinente tu comparación?')}</p><a href="#modulo/${m.id}/comparar" class="text-link">Editar mis evidencias ${icon}</a></div></details>${glossaryLinks(m.id)}</aside>`;}
function nextWorkshop(m,route){const theme=m.id===4&&route==='A'?'<a href="#semana/15" class="text-link">Continuar la semana 15: matriz temática y después medios</a>':'';const done=k=>['Revisado','Modificado después de revisar'].includes(workStatus(state,k)),other=route==='A'?'B':'A';return `<div class="next-workshop">${theme}${m.id===4&&!done(routeKey(m,other))?`<a href="#modulo/4/comparar" data-route-note="4-${other}" data-goto-field="${routeKey(m,other)}-hypothesis" class="text-link">${other==='B'?'Extensión intermedial · Semana 15':'Volver a Cervantes / Borges · Semana 14'} ${icon}</a>`:m.id<4?`<a href="#modulo/${m.id+1}/orientar" class="text-link">Después de las actividades de la unidad: ${moduleById[m.id+1].title} ${icon}</a>`:`<a href="#proyecto" class="text-link">Desarrollar mi pregunta en el ensayo final ${icon}</a>`}</div>`;}
function projectSynthesis(){return `<details class="project-synthesis"><summary>Recuperar el recorrido de mis hipótesis</summary>${modules.map(m=>{const keys=moduleKeys(m).filter(k=>m.both||k===routeKey(m,state.routes[m.id])||workStatus(state,k)!=='Sin empezar');return keys.map(key=>`<section><h3>${keyNames[key]}</h3><p class="work-status">${statusChip(keyStatus(key))}</p><div class="hypothesis-pair"><div><h4>Al empezar</h4><p class="preserve">${escape(note(key,'hypothesis'))||'Sin hipótesis inicial.'}</p></div><div><h4>Después del contraste</h4><p class="preserve">${escape(note(key,'revision'))||'Sin revisión todavía.'}</p></div></div><p class="preserve">${escape(note(key,'revisionReason'))}</p><a class="text-link" href="#modulo/${m.id}/revisar" data-route-note="${noteDestination(key)?.route||''}">Retomar esta revisión ${icon}</a></section>`).join('');}).join('')}<section><h3>Un puerto, dos traducciones</h3><p class="preserve">${escape(note('3-traduccion','translation'))||'Sin comentario todavía.'}</p><a class="text-link" href="#modulo/3/traduccion">Volver al cotejo ${icon}</a></section></details>`;}

function projectWork(){const keys=Object.keys(taskNotes).filter(key=>Object.values(state.notes[key]||{}).some(v=>v.trim()));return `<details class="project-work"><summary>Recuperar mis fichas, cartografía y matrices</summary><p>Selecciona el trabajo que ayuda a tu pregunta. El ensayo desarrolla un argumento; las fichas y matrices son materiales de partida, no apartados que debas reunir íntegramente.</p>${keys.length?keys.map(key=>{const dest=noteDestination(key);return `<section><h3>${escape(taskNotes[key].title)}</h3><p class="preserve">${escape(note(key,'argument'))||'Consulta las decisiones de revisión.'}</p>${note(key,'revisionReason')?`<p class="caption preserve">${escape(note(key,'revisionReason'))}</p>`:''}<a href="${dest.href}" data-goto-field="${dest.field}">Volver a esta actividad</a></section>`;}).join(''):'<p>Al escribir las actividades semanales, podrás recuperarlas aquí. Por ahora puedes formular tu pregunta provisional y seleccionar dos objetos.</p>'}</details>`;}
function notebookEntry(key,n,archived=false){const dest=noteDestination(key);return `<section class="notebook-entry"><div class="section-heading"><div><h2>${escape(keyNames[key])}</h2><p class="work-status">${archived?'<span class="archive-status">Archivada</span>':statusChip(keyStatus(key),{key})}</p></div>${!archived&&dest?`<a href="${dest.href}" class="text-link" data-route-note="${dest.route||''}" ${dest.field?`data-goto-field="${dest.field}"`:''}>Volver a la actividad ${icon}</a>`:''}</div>${Object.entries(n).filter(([,v])=>v.trim()).map(([f,v])=>`<h3>${escape(fieldLabel(key,f))}</h3><p class="preserve">${escape(v)}</p>`).join('')}</section>`;}
function notebook(){
 const entries=Object.entries(state.notes).filter(([,n])=>Object.values(n).some(v=>v.trim())),active=entries.filter(([k])=>!archivedKeys.includes(k)),archive=entries.filter(([k])=>archivedKeys.includes(k)),work=hasWork(state);
 return `${header('Portafolio personal','Mi cuaderno','Las hipótesis, evidencias y revisiones que vas construyendo durante el curso.')}<div class="storage-notice"><strong>Este cuaderno vive en este navegador.</strong><p>No se envía al docente ni se sincroniza entre dispositivos. Exporta un respaldo para conservarlo y poder recuperarlo después.</p></div><div class="export-actions">${work?button('prepare-delivery','Preparar entrega / PDF '+icon,'button primary')+button('export-md','Descargar cuaderno en texto (.md) '+icon)+button('export-json','Descargar respaldo recuperable (.json)')+button('print','Imprimir'):''}${button('import','Importar respaldo')}${work||storedRaw()?button('clear-notebook',exitIcon+'Terminar en este equipo'):''}</div><p class="save-line" data-save-status>${savedLabel()}</p><details class="backup-help"><summary>Cómo guardar y recuperar un respaldo JSON</summary><ol><li>Descarga «Respaldo recuperable (.json)» y conserva el archivo en tu carpeta personal.</li><li>Abre esta misma aplicación en el equipo o navegador donde continuarás.</li><li>En Mi cuaderno, pulsa «Importar respaldo», elige el archivo y revisa el resumen.</li><li>Confirma «Reemplazar con este respaldo». Si hay trabajo actual, respáldalo primero.</li></ol><p>Recupera notas, ensayo, revisiones, relaciones y elecciones de entrega. El archivo contiene tu trabajo personal. No incluye el código de la web ni los libros enlazados.</p></details><div id="notebook-entries">${active.length?active.map(([key,n])=>notebookEntry(key,n)).join(''):'<div class="empty-state"><h2>Tu primera lectura empieza aquí.</h2><p>Abre el taller de comparación del módulo 1 para registrar tu hipótesis y los pasajes de Palacio y Machado. Tus notas aparecerán en este espacio.</p><a href="#modulo/1/comparar" class="button primary">Empezar a comparar Palacio y Machado</a></div>'}${state.relations.length?'<section><h2>Relaciones entre obras</h2>'+relationsView()+'</section>':''}${archive.length?`<details class="notebook-archive"><summary>Notas de la versión anterior · ${count(archive.length,'sección','secciones')}</summary><p>Archivadas para consulta y exportación. No cuentan para las entregas ni para el avance de las actividades actuales.</p>${archive.map(([key,n])=>notebookEntry(key,n,true)).join('')}</details>`:''}</div>`;
}
function render({keep=false}={}){const parts=location.hash.slice(1).split('/');const requestedWeek=parts[0]==='semana'?Number(parts[1]):null;current=requestedWeek&&weeks.some(w=>w.week===requestedWeek)?{page:'modulo',module:Math.ceil(requestedWeek/4),step:'orientar',week:requestedWeek}:{page:parts[0]||'inicio',module:Number(parts[1])||1,step:parts[2]||'orientar',week:null};if(current.page==='modulo'&&(!moduleById[current.module]||!moduleSteps(current.module).some(s=>s[0]===current.step)))current.page='no-encontrado';const pages={inicio:home,introduccion:intro,modulo:modulePage,biblioteca:library,proyecto:project,cuaderno:notebook};const lockedPage=locked&&(viewOnly?['proyecto','cuaderno']:['introduccion','modulo','proyecto','cuaderno']).includes(current.page);main.innerHTML=(lockedPage?lockView:pages[current.page]||(()=>`${header('','Esta página no existe','Vuelve al recorrido para continuar.')}<a href="#inicio" class="button primary">Volver al recorrido</a>`))();if(locked&&viewOnly&&['introduccion','modulo'].includes(current.page))main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',consultBar());renderSidebar();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===current.page||(a.dataset.nav==='inicio'&&['modulo','introduccion'].includes(current.page));if(active)a.setAttribute('aria-current',a.dataset.nav===current.page?'page':'true');else a.removeAttribute('aria-current');});const stepTitle=current.page==='modulo'?moduleSteps(current.module).find(s=>s[0]===current.step)[1]+' · ':'';document.title=lockedPage?'¿Es tuyo este cuaderno? · Literatura comparada':(current.page==='modulo'?stepTitle+moduleById[current.module].title:({inicio:'Seminario y taller',biblioteca:'Biblioteca',proyecto:'Ensayo final',cuaderno:'Mi cuaderno',introduccion:'Antes de comparar'}[current.page]||'Página no encontrada'))+' · Literatura comparada';(main.querySelector('h1')||main).setAttribute('tabindex','-1');if(!keep){window.scrollTo({top:0,behavior:'instant'});(main.querySelector('h1')||main).focus({preventScroll:true});}if(current.week&&!lockedPage){const week=main.querySelector('#week-'+current.week);if(week){week.open=true;week.querySelector('summary').focus({preventScroll:true});week.scrollIntoView({block:'start',behavior:'instant'});}}scrollHints(main.querySelector('.step-nav'));updateSaveStatus();if(justFinished&&current.page==='inicio')$('#done-title')?.focus({preventScroll:true});if(pendingFocus){const target=document.getElementById(pendingFocus);pendingFocus='';if(target){let parent=target.parentElement;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}target.scrollIntoView({block:'center',behavior:'instant'});target.focus({preventScroll:true});}}}
let pendingFocus='',finishAfterClear=false,justFinished=false;
// Horizontal strips on narrow screens: keep the current item visible and show when more items are hidden.
function scrollHints(el){if(!el)return;const update=()=>{el.classList.toggle('more-start',el.scrollLeft>2);el.classList.toggle('more-end',el.scrollLeft+el.clientWidth<el.scrollWidth-2);};const active=el.querySelector('[aria-current]');if(active&&el.scrollWidth>el.clientWidth)el.scrollLeft+=active.getBoundingClientRect().left-el.getBoundingClientRect().left-(el.clientWidth-active.offsetWidth)/2;update();el.addEventListener('scroll',update,{passive:true});}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportFile(json=false){download(json?JSON.stringify(state,null,2):exportMarkdown(state),fileName(json?'respaldo':'cuaderno'),json?'application/json':'text/markdown;charset=utf-8');toast(json?'Respaldo preparado para descargar. Si el equipo es compartido, guárdalo fuera de él y bórralo de la carpeta Descargas.':'Cuaderno en texto preparado para descargar.',json?9000:5000);}
const presenter=createPresenter($('#class-dialog'));
let selectedWeek=null;function showClass(){const m=current.page==='introduccion'?0:current.module,week=current.week||(selectedWeek&&Math.ceil(selectedWeek/4)===m?selectedWeek:null)||(current.page==='modulo'?(current.step==='traduccion'?11:(m-1)*4+1):null);presenter.show(m,state.routes[m]||'A',current.page==='modulo'?current.step:'',week);}
function dialogAction(title,body,action,label){$('#action-dialog').innerHTML=`<h2 id="action-title">${title}</h2>${body}<div class="export-actions">${button('cancel-action','Cancelar','button','autofocus')}${button(action,label,'button primary')}</div><p id="action-error" role="alert"></p>`;$('#action-dialog').showModal();}
function refreshWorkStatus(){document.querySelectorAll('[data-work-status]').forEach(el=>{const s=keyStatus(el.dataset.workStatus);el.dataset.status=statusSlug[s];el.innerHTML=chipInner(s);});const b=$('[data-action=review]');if(b){const [label,cls]=reviewLabel(b.dataset.key);b.textContent=label;b.className=cls;}renderSidebar();document.querySelectorAll('[data-module-progress]').forEach(el=>{const m=moduleById[el.dataset.moduleProgress];if(m)el.outerHTML=progressView(m,el.classList.contains('stage-state')?'stage-state':'');});const nw=main.querySelector('.next-workshop');if(nw&&current.page==='modulo'){const mm=moduleById[current.module];nw.outerHTML=nextWorkshop(mm,state.routes[mm.id]||'A');}const nav=main.querySelector('.step-nav');if(nav&&current.page==='modulo'){const m=moduleById[current.module],links=stepLinks(m,routeKey(m,state.routes[m.id]));if(nav.dataset.sig!==links){nav.innerHTML=links;nav.dataset.sig=links;}}}
// A route review can be registered before its module can close; the route label then says «Revisión registrada».
function keyStatus(key){if(key==='3-traduccion'){const t=state.notes['3-traduccion']||{},m3=moduleStatus(moduleById[3]);return t.translation?.trim()&&['Revisado','Modificado después de revisar'].includes(m3)?m3:Object.values(t).some(v=>v.trim())?'En construcción':'Sin empezar';}const s=workStatus(state,key),m=moduleById[key[0]];if(s==='Revisado'&&m&&!['Revisado','Modificado después de revisar'].includes(moduleStatus(m)))return 'Revisión registrada';return s;}
const isClosed=m=>!!m&&moduleStatus(m)==='Revisado';
const closedMessage=m=>m.id===3?'Taller comparativo y comentario de traducción revisados.':m.both?'Los dos talleres comparativos están revisados.':`Taller del módulo ${m.id} revisado.`;
function dossierStatus(){return Object.values(state.notes.ensayo||{}).some(v=>v.trim())||state.relations.length?'En construcción':'Sin empezar';}
function moduleMissing(m,route){if(m.id===3&&!note('3-traduccion','translation').trim())return '<a href="#modulo/3/traduccion" data-goto-field="3-traduccion-translation">comentario de traducción</a>';if(m.both){const other=route==='A'?'B':'A';if(!['Revisado','Modificado después de revisar'].includes(workStatus(state,routeKey(m,other))))return `<a href="#modulo/4/comparar" data-route-note="4-${other}" data-goto-field="${routeKey(m,other)}-hypothesis">taller ${other}</a>`;}return '';}
function reviewLabel(key){return workStatus(state,key)==='Revisado'?['Actualizar revisión','button']:['Registrar revisión','button primary'];}
function reviewButton(key){const [label,cls]=reviewLabel(key);return button('review',label,cls,`data-key="${key}"`);}
function stepHasWork(m,key,id){const n=state.notes[key]||{},has=f=>!!n[f]?.trim();if(id==='comparar')return ['hypothesis','evidenceA','locatorA','evidenceB','locatorB','difference'].some(has);if(id==='argumentar')return ['objection','argument'].some(has);if(id==='revisar')return ['revision','revisionReason'].some(has)||state.completed.includes(key);if(id==='traduccion')return Object.values(state.notes['3-traduccion']||{}).some(v=>v.trim());return false;}
function stepLinks(m,key){return moduleSteps(m.id).map(([id,title],i)=>`<a href="#modulo/${m.id}/${id}" ${id===current.step?'aria-current="step"':''}><span class="step-number">0${i+1}</span>${title}${stepHasWork(m,key,id)?'<svg viewBox="0 0 24 24" aria-hidden="true" class="icon step-mark"><circle cx="12" cy="12" r="3.5" fill="currentColor"/></svg><span class="sr-only"> (con notas)</span>':''}</a>`).join('');}
function clearFieldError(el){el.removeAttribute('aria-invalid');const err=document.getElementById(el.id+'-error');if(err)err.textContent='';}
function reviewError(key){const missing=['argument','revision','revisionReason'].filter(f=>!note(key,f).trim());if(!missing.length)return false;$('#review-error').innerHTML=`<p>Para registrar la revisión falta:</p><ul>${missing.map(f=>`<li><a href="${f==='argument'?'#modulo/'+current.module+'/argumentar':'#'+key+'-'+f}" ${f==='argument'?'data-goto-field="'+key+'-argument"':'data-focus-field="'+key+'-'+f+'"'}>${f==='argument'?'Escribir mi argumento':fieldNames[f]}</a></li>`).join('')}</ul>`;for(const f of missing){const el=document.getElementById(key+'-'+f);if(el){el.setAttribute('aria-invalid','true');document.getElementById(el.id+'-error').innerHTML='<span><strong>Falta:</strong> completa este apartado antes de registrar la revisión.</span>';}}const target=document.getElementById(key+'-'+missing[0]);if(target)target.focus();else $('#review-error a').focus();return true;}
function resetRelationForm(){relationEdit=-1;$('#relation-form')?.reset();if($('#relation-submit'))$('#relation-submit').innerHTML='Añadir relación '+icon;const cancel=$('[data-action=cancel-relation]');if(cancel)cancel.hidden=true;$('#relation-form')?.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));if($('#relation-error'))$('#relation-error').textContent='';}
function editRelation(index){const r=state.relations[index];if(!r)return;relationEdit=index;for(const [id,value] of [['relation-from',r.from],['relation-to',r.to]]){const select=document.getElementById(id);if(![...select.options].some(o=>o.value===value))select.add(new Option(value,value));select.value=value;}$('#relation-type').value=r.type;$('#relation-evidence').value=r.evidence;for(const f of ['mediator','date','medium'])$('#relation-'+f).value=r[f]||'';if(['mediator','date','medium'].some(f=>r[f]))$('.mediation-fields').open=true;$('#relation-submit').textContent='Guardar cambios de la relación';$('[data-action=cancel-relation]').hidden=false;$('#relation-from').focus();}

document.addEventListener('input',e=>{if(mutationBusy)return;const el=e.target;if(el.matches('[data-note]')&&!locked){const mod=moduleById[el.dataset.note[0]],closedBefore=isClosed(mod);clearFieldError(el);lastEdited=el.id;writeNote(state,el.dataset.note,el.dataset.field,el.value);if(mod&&!closedBefore&&isClosed(mod))toast(closedMessage(mod));save();const counter=document.querySelector(`[data-count="${el.id}"]`);if(counter)counter.textContent=count(wordCount(el.value),'palabra','palabras');refreshWorkStatus();if($('#review-error'))$('#review-error').textContent='';}if(el.matches('#library-search,.library-filters select,#filter-audience'))filterLibrary();});
document.addEventListener('change',e=>{if(e.target.id==='week-jump'&&e.target.value){location.hash='semana/'+e.target.value;return;}if(e.target.matches('.library-filters select,#filter-audience'))filterLibrary();});
document.addEventListener('click',async e=>{
 if(e.target.closest('.skip')){e.preventDefault();(main.querySelector('h1')||main).focus();return;}
 if(e.target.closest('[data-owner-ok]'))unlockNotebook();
 const weekSummary=e.target.closest('.weekly-plan>details>summary');if(weekSummary)selectedWeek=Number(weekSummary.parentElement.id.slice(5));const classWeek=e.target.closest('[data-class-week]');if(classWeek){const week=Number(classWeek.dataset.classWeek),module=Math.ceil(week/4);presenter.show(module,state.routes[module]||'A','',week,classWeek.dataset.classDay||null);return;}
 const goto=e.target.closest('[data-goto-field]');if(goto){pendingFocus=goto.dataset.gotoField;if(goto.getAttribute('href')===location.hash){const target=document.getElementById(pendingFocus);if(target){for(let el=target.parentElement;el;el=el.parentElement)if(el.tagName==='DETAILS')el.open=true;target.focus();pendingFocus='';}}}
 const focusLink=e.target.closest('[data-focus-field]');if(focusLink){e.preventDefault();document.getElementById(focusLink.dataset.focusField)?.focus();return;}
 const noteLink=e.target.closest('[data-route-note]');if(noteLink){const [m,r]=noteLink.dataset.routeNote.split('-');if(['2','3','4'].includes(m)&&['A','B'].includes(r)){state.routes[m]=r;save();if(location.hash===noteLink.getAttribute('href'))render();}}
 const b=e.target.closest('[data-action]');if(!b||mutationBusy)return;const action=b.dataset.action;
 if(locked&&['review','export-md','export-json','print','import','prepare-delivery','print-delivery'].includes(action)){toast('Para trabajar con un cuaderno, confirma primero si el guardado es tuyo.');return;}
 if(action==='route'){const compact=!!b.closest('.route-compact');state.routes[current.module]=b.dataset.route;save();const y=window.scrollY;render();if(compact&&$('.route-compact'))$('.route-compact').open=true;window.scrollTo({top:y,behavior:'instant'});document.querySelector(`[data-action="route"][data-route="${b.dataset.route}"]`)?.focus({preventScroll:true});}
 if(action==='review'){if(reviewError(b.dataset.key))return;const closedBefore=isClosed(moduleById[current.module]);markReviewed(state,b.dataset.key);$('#review-error').textContent='';refreshWorkStatus();const ok=await save();toast(!ok?'Revisión conservada en esta pestaña. Descarga una copia.':moduleMissing(moduleById[current.module],state.routes[current.module]||'A')?'Revisión registrada. El recorrido del módulo incluye también: '+moduleMissing(moduleById[current.module],state.routes[current.module]||'A').replace(/<[^>]+>/g,'')+'.':!closedBefore&&isClosed(moduleById[current.module])?'Revisión registrada. '+closedMessage(moduleById[current.module]):'Revisión registrada. Puedes seguir editando.');}
 if(action==='reset-filters'){document.querySelectorAll('.library-filters input,.library-filters select').forEach(el=>el.value='');$('#filter-audience').value='Lectura común';filterLibrary();$('#library-search').focus();}
 if(action==='export-md')exportFile();if(action==='export-json')exportFile(true);
 if(action==='print'){if(current.page!=='cuaderno'){location.hash='cuaderno';setTimeout(()=>window.print(),200);}else window.print();}
 if(action==='import')$('#import-file').click();
 if(action==='cancel-import')$('#import-dialog').close();
 if(action==='confirm-import'&&pendingImport){mutationBusy=true;b.disabled=true;const incoming=pendingImport;const result=await session.save(incoming);mutationBusy=false;b.disabled=false;if(!result.ok){storageNotice(result.reason);$('#import-error').textContent='No se reemplazó el cuaderno. Resuelve el aviso de guardado antes de volver a importar.';return;}state=incoming;state.updatedAt=result.updatedAt;owned=true;lastStamp=0;markActive();storageBlocked=false;savePhase='saved';$('#storage-warning')?.remove();$('#import-dialog').close();render();toast('Respaldo recuperado en este navegador.');}
 if(action==='owner-ok'){const back=resumeAt&&resumeAt.hash===location.hash?resumeAt:null;resumeAt=null;unlockNotebook();if(back){render({keep:true});window.scrollTo({top:back.y,behavior:'instant'});const el=back.id&&document.getElementById(back.id);(el||main.querySelector('h1')).focus({preventScroll:true});}else render();}
 if(action==='consult'){viewOnly=true;if(current.page==='inicio')location.hash='#introduccion';else render();toast('Modo consulta: el cuaderno guardado sigue oculto y no se guarda nada.');}
 if(action==='not-mine')dialogAction('Empezar con un cuaderno vacío','<p>Se borrará de este navegador el cuaderno guardado aquí, sin mostrar ni descargar su contenido.</p><p>Si el cuaderno es tuyo, cancela y continúa tu trabajo.</p>','confirm-clear','Vaciar y empezar');
 if(action==='clear-notebook'||action==='not-mine')finishAfterClear=action==='clear-notebook';
 if(action==='clear-notebook'){const sections=Object.values(state.notes).filter(n=>Object.values(n).some(v=>v.trim())).length;dialogAction('Terminar en este equipo',`<p>Se borrará de este navegador: ${count(sections,'sección con texto','secciones con texto')}, ${count(state.relations.length,'relación','relaciones')} y ${count(state.completed.length,'revisión registrada','revisiones registradas')}. El siguiente estudiante empezará con un cuaderno vacío.</p><p><strong>No se puede deshacer: lo que no hayas descargado antes se pierde.</strong></p><p>Cierra también las otras pestañas del curso. Los archivos que hayas descargado antes no se borran.</p>`,'confirm-clear','Vaciar y terminar');}
 if(action==='dismiss-warning'){$('#storage-warning')?.remove();(main.querySelector('h1')||main).focus();}
 if(action==='load-stored')dialogAction('Abrir la versión guardada','<p>Los textos de esta pestaña se reemplazarán por la versión guardada en el navegador. Lo que escribiste aquí y no esté en esa versión se perderá.</p>','confirm-load','Abrir versión guardada');
 if(action==='keep-local')dialogAction('Usar el texto de esta pestaña','<p>La versión guardada en el navegador se reemplazará por los textos de esta pestaña. Lo escrito en la otra pestaña que no esté aquí se perderá.</p><p>Después, cierra la otra pestaña del curso.</p>','confirm-keep','Usar esta versión');
 if(action==='confirm-keep'){mutationBusy=true;b.disabled=true;await session.idle();const raw=storedRaw();if(raw===null){mutationBusy=false;$('#action-dialog').close();wipeAfterRemoteDelete();return;}session=createSession({storage,lock,initialRaw:raw});savePhase='saved';const ok=await save();mutationBusy=false;b.disabled=false;if(!ok){$('#action-error').textContent='No se pudo guardar esta versión. Vuelve a intentarlo.';return;}$('#storage-warning')?.remove();$('#action-dialog').close();updateSaveStatus();toast('Se guardó la versión de esta pestaña.');}
 if(action==='cancel-action')$('#action-dialog').close();
 if(action==='confirm-clear'){mutationBusy=true;b.disabled=true;const result=await session.clear();mutationBusy=false;b.disabled=false;if(!result.ok){storageNotice(result.reason);$('#action-error').textContent='No se borró el cuaderno. Hay cambios en otra pestaña o el almacenamiento no está disponible.';return;}state=freshState();pendingImport=null;relationEdit=-1;storageBlocked=false;savePhase='saved';$('#import-file').value='';document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('#import-dialog').innerHTML='';$('#action-dialog').innerHTML='';$('#storage-warning')?.remove();held=null;locked=false;viewOnly=false;disown();if(finishAfterClear){justFinished=true;if(location.hash==='#inicio'||!location.hash)render();else location.hash='#inicio';}else{render();toast('Cuaderno borrado de este navegador.');}}
 if(action==='confirm-load'){mutationBusy=true;b.disabled=true;await session.idle();const next=loadState(storage);mutationBusy=false;b.disabled=false;if(next.error){$('#action-error').textContent=next.error;return;}state=next.state;session=createSession({storage,lock,initialRaw:next.raw});storageBlocked=false;savePhase='saved';$('#storage-warning')?.remove();$('#action-dialog').close();render();toast('Se abrió la versión guardada.');}
 if(action==='edit-relation'){const index=Number(b.dataset.index);if(current.page!=='proyecto'){location.hash='proyecto';setTimeout(()=>editRelation(index),0);}else editRelation(index);}
 if(action==='cancel-relation')resetRelationForm();
 if(action==='delete-relation'){const index=Number(b.dataset.index),r=state.relations[index];dialogAction('Eliminar esta relación',`<p>${escape(r.from)} → ${escape(r.to)}</p><p>Se eliminarán este vínculo y su explicación. Las notas de los módulos se conservarán.</p>`,'confirm-delete','Eliminar relación');$('[data-action=confirm-delete]').dataset.index=index;}
 if(action==='confirm-delete'){mutationBusy=true;b.disabled=true;state.relations.splice(Number(b.dataset.index),1);await save();mutationBusy=false;$('#action-dialog').close();if(current.page==='proyecto'){resetRelationForm();$('#relations-list').innerHTML=relationsView();if($('#desk-map'))$('#desk-map').innerHTML=relationDiagram(state.relations);$('#relation-from').focus();}else render();toast('Relación eliminada de esta copia del cuaderno.');}
});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='relation-form')return;e.preventDefault();const from=$('#relation-from'),to=$('#relation-to'),evidence=$('#relation-evidence');for(const el of [from,to,evidence])el.removeAttribute('aria-invalid');
 const invalid=!from.value?from:!to.value||from.value===to.value?to:!evidence.value.trim()?evidence:null;
 if(invalid){$('#relation-error').textContent=invalid===evidence?'Añade la evidencia, su localizador y el límite de la relación.':'Selecciona dos obras diferentes para construir la relación.';invalid.setAttribute('aria-invalid','true');invalid.focus();return;}
 if(relationEdit<0&&state.relations.length>=100){$('#relation-error').textContent='Has alcanzado cien relaciones. Puedes editar o eliminar las existentes.';return;}
 const r={from:from.value,to:to.value,type:$('#relation-type').value,evidence:evidence.value.trim(),mediator:$('#relation-mediator').value.trim(),date:$('#relation-date').value.trim(),medium:$('#relation-medium').value.trim()};const editing=relationEdit>=0;if(editing)state.relations[relationEdit]=r;else state.relations.push(r);save();$('#relations-list').innerHTML=relationsView();if($('#desk-map'))$('#desk-map').innerHTML=relationDiagram(state.relations);resetRelationForm();toast(editing?'Relación actualizada.':'Relación añadida al proyecto.');
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw new Error('El archivo supera el tamaño máximo de 2 MB.');pendingImport=validateState(JSON.parse(await file.text()));const entries=Object.entries(pendingImport.notes).filter(([,n])=>Object.values(n).some(v=>v.trim()));$('#import-dialog').innerHTML=`<h2 id="import-title">Recuperar un cuaderno</h2><p>${count(entries.length,'sección con texto','secciones con texto')} · ${count(pendingImport.relations.length,'relación','relaciones')}.</p><ul>${entries.map(([key])=>`<li>${keyNames[key]}</li>`).join('')}</ul><p>Importarlo reemplazará el cuaderno de este navegador. Descarga antes un respaldo si quieres conservarlo.</p><div class="export-actions">${button('export-json','Respaldar el cuaderno actual')}${button('cancel-import','Cancelar','button','autofocus')}${button('confirm-import','Reemplazar con este respaldo','button primary')}</div><p id="import-error" role="alert"></p>`;$('#import-dialog').showModal();}catch(err){pendingImport=null;toast('No se importó el archivo. '+(err instanceof SyntaxError?'El contenido no es JSON válido.':err.message));}finally{e.target.value='';}});
$('#import-dialog').addEventListener('close',()=>{pendingImport=null;$('#import-dialog').innerHTML='';});
document.querySelectorAll('#action-dialog,#import-dialog').forEach(dialog=>dialog.addEventListener('cancel',e=>{if(mutationBusy)e.preventDefault();}));
$('#class-toggle').addEventListener('click',showClass);
// Another tab wrote. A tab with no edits of its own follows it quietly; only diverging edits are a conflict.
let syncTimer,lastSyncToast=0;
window.addEventListener('storage',e=>{if((e.key!==STORAGE_KEY&&e.key!==null)||!session.changed())return;if(storedRaw()===null&&!mutationBusy){wipeAfterRemoteDelete();return;}clearTimeout(syncTimer);syncTimer=setTimeout(syncFromOtherTab,800);});
function hasLocalChanges(){if(pendingSaves||mutationBusy||savePhase!=='saved')return true;const form=$('#relation-form');return !!form&&(relationEdit>=0||!!$('#relation-from').value||!!$('#relation-to').value||!!$('#relation-evidence').value.trim()||['mediator','date','medium'].some(f=>$('#relation-'+f)?.value.trim()));}
function syncFromOtherTab(){if(!session.changed())return;if(storedRaw()===null){if(!mutationBusy)wipeAfterRemoteDelete();return;}if(hasLocalChanges()){storageNotice('conflict');return;}const next=loadState(storage);if(next.error){storageNotice('conflict');return;}session=createSession({storage,lock,initialRaw:next.raw});if(!locked&&!owned&&hasWork(next.state)){held=next.state;state=freshState();locked=true;viewOnly=false;resumeAt=null;render();return;}if(locked){held=next.state;document.querySelectorAll('[data-lock-meta]').forEach(el=>el.textContent=lockMeta());return;}state=next.state;const y=window.scrollY,active=document.activeElement,id=active&&active!==document.body&&!active.matches('h1')?active.id:'',sel=active&&typeof active.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null;if(current.page==='biblioteca'){renderSidebar();updateSaveStatus();}else{render({keep:true});window.scrollTo({top:y,behavior:'instant'});const el=id&&document.getElementById(id);if(el){el.focus({preventScroll:true});if(sel&&el.setSelectionRange)el.setSelectionRange(...sel);}}if(Date.now()-lastSyncToast>60000){lastSyncToast=Date.now();toast('Actualizado con cambios de otra pestaña.');}}
document.addEventListener('focusin',e=>{const item=e.target.closest?.('.step-nav a,.sidebar nav a');if(item&&item.parentElement.scrollWidth>item.parentElement.clientWidth)item.scrollIntoView({block:'nearest',inline:'nearest'});});
window.addEventListener('beforeunload',e=>{if(pendingSaves||((savePhase==='conflict'||savePhase==='unavailable')&&hasWork(state))){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{relationEdit=-1;render();});
ownerCheck();render();if(loaded.error)storageNotice('unavailable');
for(const type of ['pointerdown','keydown','input','wheel','touchstart'])document.addEventListener(type,markActive,{passive:true,capture:true});
setInterval(()=>{if(!locked&&hasWork(state)&&Date.now()-lastActive>IDLE_LOCK)lockNotebook();},30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!locked&&hasWork(state)&&Date.now()-lastActive>IDLE_LOCK)lockNotebook();});

// New reading and writing controls reuse the existing notebook and save protocol.
let essaySelection=null;
document.addEventListener('selectionchange',()=>{const el=$('#ensayo-argument');if(el&&document.activeElement===el)essaySelection={start:el.selectionStart,end:el.selectionEnd};});
document.addEventListener('click',async e=>{
 const term=e.target.closest('[data-concept]');if(term&&conceptById[term.dataset.concept]){$('#concept-dialog').innerHTML=conceptHtml(term.dataset.concept);$('#concept-dialog').showModal();return;}
 if(e.target.closest('[data-close-concept]')){$('#concept-dialog').close();return;}
 const tab=e.target.closest('[data-desk-tab]');if(tab){activateDeskTab(tab);return;}
 const insert=e.target.closest('[data-insert-evidence]');if(insert&&!locked){const passage=collectEvidence(state).find(p=>p.id===insert.dataset.insertEvidence),el=$('#ensayo-argument');if(!passage||!el)return;const result=insertPassage(el.value,essaySelection?.start??el.value.length,essaySelection?.end??el.value.length,passage);if(result.text.length>60000){toast('El borrador alcanzaría el límite del campo; revisa su extensión.');return;}el.value=result.text;el.dispatchEvent(new Event('input',{bubbles:true}));el.focus({preventScroll:true});el.setSelectionRange(result.caret,result.caret);essaySelection={start:result.caret,end:result.caret};toast(passage.locator.trim()?'Pasaje insertado. Revisa su cita y desarrolla el análisis.':'Pasaje insertado con localizador pendiente.');return;}
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='prepare-delivery'&&!locked){showDelivery();return;}
 if(action==='close-delivery'){$('#delivery-dialog').close();return;}
 if(action==='print-delivery'&&!locked){await session.idle();const section=document.createElement('section');section.id='delivery-print';section.innerHTML=deliveryHtml(state);document.body.append(section);document.body.dataset.print='delivery';window.print();return;}
 const reference=e.target.closest('#concept-dialog a');if(reference&&!reference.target)$('#concept-dialog').close();
});
function activateDeskTab(tab){const parent=tab.closest('.essay-desk');parent.querySelectorAll('[role=tab]').forEach(el=>{const active=el===tab;el.setAttribute('aria-selected',String(active));el.tabIndex=active?0:-1;});parent.querySelectorAll('[role=tabpanel]').forEach(el=>el.hidden=el.id!=='desk-'+tab.dataset.deskTab);tab.focus({preventScroll:true});}
document.addEventListener('keydown',e=>{const tab=e.target.closest?.('[data-desk-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')],i=tabs.indexOf(tab);activateDeskTab(tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length]);});
function showDelivery(){const choices=annexOptions(state),d=state.delivery;$('#delivery-dialog').innerHTML=`<div class="dialog-heading"><h2 id="delivery-title">Preparar mi entrega</h2>${button('close-delivery','Cerrar','button','autofocus')}</div><p>Ensayo, consigna y referencias forman el cuerpo. Selecciona los anexos pertinentes y revisa la vista previa.</p><fieldset class="delivery-choices"><legend>Anexos que compartiré</legend>${choices.map(c=>`<label><input type="checkbox" data-annex="${escape(c.key)}" ${d.annexes.includes(c.key)?'checked':''}> ${escape(c.title)}</label>`).join('')||'<p>Todavía no hay actividades con texto para anexar.</p>'}<label><input type="checkbox" data-delivery-option="includeMap" ${d.includeMap?'checked':''}> Mapa y fuentes de las relaciones</label><label><input type="checkbox" data-delivery-option="includeAssessment" ${d.includeAssessment?'checked':''}> Autoevaluación con la rúbrica</label></fieldset><div class="export-actions">${button('print-delivery','Imprimir / guardar como PDF','button primary')}${button('export-json','Guardar respaldo recuperable (.json)')}</div><p class="caption">En el diálogo de impresión elige «Guardar como PDF». Para continuar editando después, conserva también el JSON.</p><div id="delivery-preview" aria-label="Vista previa de la entrega">${deliveryHtml(state)}</div>`;$('#delivery-dialog').showModal();}
document.addEventListener('change',e=>{if(locked)return;const annex=e.target.dataset.annex,option=e.target.dataset.deliveryOption;if(annex){state.delivery.annexes=state.delivery.annexes.filter(k=>k!==annex);if(e.target.checked)state.delivery.annexes.push(annex);}else if(['includeMap','includeAssessment'].includes(option))state.delivery[option]=e.target.checked;else return;save();$('#delivery-preview').innerHTML=deliveryHtml(state);});
function cleanupDeliveryPrint(){document.body.removeAttribute('data-print');$('#delivery-print')?.remove();}
window.addEventListener('afterprint',cleanupDeliveryPrint);
$('#delivery-dialog').addEventListener('close',()=>{$('#delivery-dialog').innerHTML='';cleanupDeliveryPrint();});
$('#concept-dialog').addEventListener('close',()=>$('#concept-dialog').innerHTML='');

